function sharedWithRepeats(a: number[], b: number[]): number[] {
  const used = new Array<boolean>(b.length).fill(false);
  const out: number[] = [];
  for (const v of a) {
    for (let j = 0; j < b.length; j++) {
      if (!used[j] && b[j] === v) { used[j] = true; out.push(v); break; }
    }
  }
  return out;
}

